const logger = {};
module.exports = logger;
const tafLogs = require('@taf/taf-logs');

logger.error = new tafLogs('TafDate', 'error', { logTo: tafLogs.LogTo.Local });
logger.exception = new tafLogs('TafDate', 'exception', { logTo: tafLogs.LogTo.Local });
logger.dcache = new tafLogs('TafDate', 'dcache', { logTo: tafLogs.LogTo.Local });
